:root {
  /* KESARI Official Studio Palette */
  --color-obsidian: #0A0A0A;
  --color-warm-ivory: #F5F0E8;
  --color-stage-orange: #FF8248;
  --color-stage-orange-hover: #FF9866;
  --color-charcoal: #292522;
  --color-charcoal-elevated: #36312C;
  --color-charcoal-border: rgba(245, 240, 232, 0.1);

  /* Primary Brand Tokens */
  --color-brand-saffron: #FF8248;
  --color-brand-saffron-hover: #FF9866;
  --color-brand-saffron-subtle: rgba(255, 130, 72, 0.14);
  --color-brand-saffron-glow: rgba(255, 130, 72, 0.32);
  --color-brand-gold: #FFB37C;

  /* Aliased for component CSS backwards-compatibility */
  --color-royal-blue: #FF8248;
  --color-royal-blue-deep: #E66A30;
  --color-electric-lime: #FF8248;
  --color-lime-glow: rgba(255, 130, 72, 0.32);
  --color-crimson: #E05342;
  --color-sky-blue: #FFB37C;
  --color-pale-blue-bg: #292522;

  /* Surfaces & Neutrals */
  --color-pure-white: #F5F0E8;
  --color-true-black: #0A0A0A;
  --color-card-dark: #292522;
  --color-card-surface-elevated: #36312C;
  --color-muted-gray: #A8A29A;
  --color-light-gray: #292522;
  --color-border-subtle: rgba(245, 240, 232, 0.1);
  --color-border-focus: rgba(255, 130, 72, 0.5);
  --color-dashed-line: rgba(245, 240, 232, 0.2);

  /* Typography */
  --font-family-display: 'Plus Jakarta Sans', 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-family-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-family-mono: 'Space Grotesk', ui-monospace, monospace;

  /* Typography Scale */
  --text-h1: 38px;
  --text-h2: 32px;
  --text-h3: 22px;
  --text-title: 19px;
  --text-subtitle: 15px;
  --text-caption: 13px;
  --text-micro: 11px;

  /* Radii - refined, modern architecture */
  --radius-xs: 6px;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-pill: 9999px;

  /* Premium Shadows - diffuse and realistic */
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.25);
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.35);
  --shadow-lg: 0 20px 48px -8px rgba(0, 0, 0, 0.55);
  --shadow-card: 0 8px 30px rgba(0, 0, 0, 0.35);
  --shadow-lime: 0 4px 18px rgba(224, 122, 40, 0.25);

  /* Transitions */
  --transition-fast: 0.16s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-smooth: 0.24s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset & Global Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  min-height: 100%;
  background-color: var(--color-true-black);
  color: var(--color-pure-white);
  font-family: var(--font-family-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  letter-spacing: -0.01em;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  outline: none;
  transition: transform var(--transition-fast), filter var(--transition-fast), background-color var(--transition-fast), border-color var(--transition-fast);
}

button:active {
  transform: scale(0.97);
}

/* Minimal Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.14);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(224, 122, 40, 0.5);
}

button:focus-visible, a:focus-visible {
  outline: 2px solid var(--color-brand-saffron);
  outline-offset: 3px;
}
a { -webkit-tap-highlight-color: transparent; }
button, input { -webkit-tap-highlight-color: transparent; }

