/* Mobile Bottom Navigation Dock */
.mobile-bottom-nav-dock {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 900;
  background: rgba(10, 12, 18, 0.94);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 12px max(10px, env(safe-area-inset-bottom)) 12px;
  box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.5);
}

@media (max-width: 768px) {
  .mobile-bottom-nav-dock {
    display: block;
  }
  /* Give body/main clearance above mobile bottom nav */
  .web-explore-view,
  .web-wallet-view,
  .web-favorites-view {
    padding-bottom: 84px !important;
  }
}

.mobile-bottom-nav-container {
  display: flex;
  align-items: center;
  justify-content: space-around;
  max-width: 500px;
  margin: 0 auto;
}

.mobile-nav-item-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  background: transparent;
  border: none;
  padding: 6px 10px;
  cursor: pointer;
  transition: transform 0.15s ease;
  position: relative;
  -webkit-tap-highlight-color: transparent;
}

.mobile-nav-item-btn:active {
  transform: scale(0.92);
}

.mobile-nav-icon-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
}

.mobile-nav-label {
  font-family: var(--font-family-body);
  font-size: 11px;
  font-weight: 600;
  color: #9CA3AF;
  letter-spacing: -0.2px;
  transition: color 0.15s ease;
}

/* Active State */
.mobile-nav-item-btn.active .mobile-nav-label {
  color: var(--color-electric-lime);
  font-weight: 700;
}

.mobile-nav-item-btn.active .mobile-nav-icon-wrap {
  filter: drop-shadow(0 0 8px rgba(218, 251, 113, 0.6));
}

/* Badge Pills */
.mobile-nav-badge-pill {
  position: absolute;
  top: -4px;
  right: -8px;
  min-width: 16px;
  height: 16px;
  border-radius: 9999px;
  background: var(--color-cobalt);
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
}

.mobile-nav-badge-pill.lime-dot {
  background: var(--color-crimson);
  color: #FFFFFF;
}

.mobile-nav-unread-dot {
  position: absolute;
  top: 1px;
  right: 1px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-crimson);
  box-shadow: 0 0 6px var(--color-crimson);
}

