.web-hero-section {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 24px 24px 12px;
}

.hero-banner-card {
  position: relative;
  width: 100%;
  min-height: 520px;
  border-radius: 32px;
  overflow: hidden;
  border: 1px solid rgba(245, 240, 232, 0.14);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.6), 0 0 80px rgba(255, 130, 72, 0.15);
  display: flex;
  align-items: flex-end;
}

/* Backdrop Imagery & Lighting */
.hero-image-backdrop {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.hero-backdrop-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
  transform: scale(1.02);
  transition: transform 0.6s cubic-bezier(0.19, 1, 0.22, 1);
}

.hero-banner-card:hover .hero-backdrop-img {
  transform: scale(1.05);
}

.hero-gradient-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(8, 8, 8, 0.2) 0%,
    rgba(8, 8, 8, 0.65) 50%,
    rgba(8, 8, 8, 0.95) 100%
  ),
  linear-gradient(
    90deg,
    rgba(8, 8, 8, 0.85) 0%,
    rgba(8, 8, 8, 0.4) 60%,
    transparent 100%
  );
}

.hero-glow-accent {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  pointer-events: none;
}

.hero-glow-accent.blue-glow,
.hero-glow-accent.saffron-glow {
  top: 10%;
  left: 20%;
  width: 360px;
  height: 360px;
  background: rgba(255, 130, 72, 0.25);
}

.hero-glow-accent.lime-glow {
  bottom: 15%;
  right: 15%;
  width: 300px;
  height: 300px;
  background: rgba(255, 130, 72, 0.18);
}

/* Content Inside Hero */
.hero-content-wrapper {
  position: relative;
  z-index: 2;
  width: 100%;
  padding: 48px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Status & Countdown Row */
.hero-top-status-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(218, 251, 113, 0.15);
  border: 1px solid rgba(218, 251, 113, 0.4);
  padding: 6px 14px;
  border-radius: 9999px;
  backdrop-filter: blur(12px);
}

.badge-pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-electric-lime);
  box-shadow: 0 0 10px var(--color-electric-lime);
  animation: pulseDot 1.8s infinite;
}

@keyframes pulseDot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.85); }
}

.badge-text {
  font-family: var(--font-family-body);
  font-size: 12px;
  font-weight: 800;
  color: var(--color-electric-lime);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.hero-countdown-clock {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(8, 8, 8, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.15);
  padding: 6px 14px;
  border-radius: 9999px;
  backdrop-filter: blur(14px);
}

.countdown-label {
  font-size: 12px;
  color: #9AA2B6;
  font-weight: 500;
}

.countdown-digits-wrap {
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-family-mono);
  font-size: 13px;
  font-weight: 700;
  color: #FFFFFF;
}

.countdown-digit {
  background: rgba(255, 255, 255, 0.1);
  padding: 2px 6px;
  border-radius: 4px;
}

.countdown-digit.sec-digit {
  color: var(--color-electric-lime);
  background: rgba(218, 251, 113, 0.15);
}

.countdown-sep {
  color: #7E8597;
}

/* Editorial Block */
.hero-editorial-block {
  max-width: 780px;
}

.hero-category-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 700;
  color: var(--color-sky-blue);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 8px;
}

.hero-main-title {
  font-family: var(--font-family-display);
  font-size: 56px;
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: #FFFFFF;
  margin-bottom: 12px;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.6);
}

.hero-lead-description {
  font-family: var(--font-family-body);
  font-size: 16px;
  line-height: 1.6;
  color: #C2C8D8;
  max-width: 640px;
}

/* Metadata Strip */
.hero-meta-strip {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.meta-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 8px 14px;
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 600;
  color: #E2E7F2;
  backdrop-filter: blur(10px);
}

.meta-pill.price-pill {
  background: rgba(224, 122, 40, 0.1);
  border-color: rgba(224, 122, 40, 0.3);
  color: #FFFFFF;
}

.meta-price-val {
  color: var(--color-brand-saffron);
  font-weight: 700;
  font-size: 14px;
}

/* Actions Row */
.hero-actions-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 8px;
  flex-wrap: wrap;
}

.hero-primary-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--color-brand-saffron);
  color: #FFFFFF;
  border: none;
  padding: 15px 26px;
  border-radius: 9999px;
  font-family: var(--font-family-display);
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(224, 122, 40, 0.35);
  transition: all 0.2s ease;
}

.hero-primary-cta:hover {
  background: var(--color-brand-saffron-hover);
  box-shadow: 0 10px 28px rgba(224, 122, 40, 0.5);
}

.cta-arrow {
  font-size: 18px;
  font-weight: 900;
}

.hero-audio-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #FFFFFF;
  padding: 15px 22px;
  border-radius: 9999px;
  font-family: var(--font-family-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition: all 0.2s ease;
}

.hero-audio-btn:hover {
  background: rgba(255, 255, 255, 0.16);
  border-color: rgba(255, 255, 255, 0.35);
}

.hero-audio-btn.active {
  background: rgba(0, 66, 217, 0.6);
  border-color: var(--color-royal-blue);
  box-shadow: 0 0 20px rgba(0, 66, 217, 0.5);
}

/* Sound Wave Equalizer */
.sound-equalizer-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 16px;
  margin-left: 4px;
}

.sound-equalizer-bars .bar {
  width: 3px;
  height: 4px;
  background: var(--color-electric-lime);
  border-radius: 2px;
  transition: height 0.2s ease;
}

.sound-equalizer-bars.animating .bar-1 {
  animation: eqBar 0.6s infinite ease-in-out alternate;
}
.sound-equalizer-bars.animating .bar-2 {
  animation: eqBar 0.9s infinite ease-in-out alternate 0.15s;
}
.sound-equalizer-bars.animating .bar-3 {
  animation: eqBar 0.7s infinite ease-in-out alternate 0.3s;
}
.sound-equalizer-bars.animating .bar-4 {
  animation: eqBar 0.8s infinite ease-in-out alternate 0.2s;
}

@keyframes eqBar {
  0% { height: 4px; }
  100% { height: 16px; }
}

.hero-favorite-btn {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition: all 0.2s ease;
}

.hero-favorite-btn:hover {
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.4);
}

.hero-favorite-btn.favorited {
  background: rgba(238, 61, 90, 0.2);
  border-color: var(--color-crimson);
}

/* Responsive adjustments */
@media (max-width: 1024px) {
  .hero-main-title {
    font-size: 42px;
  }
  .hero-content-wrapper {
    padding: 32px;
  }
}

@media (max-width: 768px) {
  .web-hero-section {
    padding: 8px 14px;
  }
  .hero-banner-card {
    min-height: auto;
    border-radius: 20px;
  }
  .hero-content-wrapper {
    padding: 20px 16px;
    gap: 16px;
  }
  .hero-top-status-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }
  .hero-badge-pill {
    padding: 4px 10px;
  }
  .badge-text {
    font-size: 11px;
  }
  .hero-countdown-clock {
    display: inline-flex;
    padding: 4px 10px;
    font-size: 11px;
    gap: 6px;
    background: rgba(8, 8, 8, 0.75);
    border-radius: 9999px;
  }
  .countdown-digits {
    font-size: 11px;
    gap: 2px;
  }
  .countdown-num {
    padding: 1px 3px;
    font-size: 11px;
  }
  .hero-tagline-category {
    font-size: 12px;
  }
  .hero-main-title {
    font-size: 26px;
    line-height: 1.15;
    letter-spacing: -0.5px;
    margin: 0;
  }
  .hero-lead-description {
    font-size: 13px;
    line-height: 1.45;
  }
  .hero-meta-pills-row {
    gap: 6px;
  }
  .meta-pill {
    padding: 5px 10px;
    font-size: 11px;
  }
  .hero-actions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    width: 100%;
  }
  .hero-primary-cta {
    width: 100%;
    justify-content: center;
    padding: 14px 20px;
    font-size: 14px;
  }
  .hero-audio-btn {
    flex: 1;
    min-width: 0;
    justify-content: center;
    padding: 12px 12px;
    font-size: 12px;
    gap: 6px;
  }
  .hero-favorite-btn {
    width: 44px;
    height: 44px;
    flex-shrink: 0;
  }
}

