.event-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 2000;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.event-modal-card {
  position: relative;
  width: 100%;
  max-width: 640px;
  max-height: 90vh;
  background: #11141E;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 32px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.7), 0 0 40px rgba(0, 66, 217, 0.2);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.modal-close-btn {
  position: absolute;
  top: 18px;
  right: 18px;
  z-index: 10;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(8, 8, 8, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: all 0.2s ease;
}

.modal-close-btn:hover {
  background: rgba(8, 8, 8, 0.95);
  transform: scale(1.08);
}

/* Banner Art */
.modal-banner-art {
  position: relative;
  width: 100%;
  height: 220px;
  overflow: hidden;
  flex-shrink: 0;
}

.modal-art-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.modal-art-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(8, 8, 8, 0.3) 0%,
    rgba(17, 20, 30, 0.95) 100%
  );
}

.modal-top-tag-row {
  position: absolute;
  top: 18px;
  left: 20px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.modal-category-chip {
  background: rgba(8, 8, 8, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #FFFFFF;
  padding: 5px 12px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  backdrop-filter: blur(10px);
}

.modal-fav-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(8, 8, 8, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(10px);
}

.modal-fav-btn.active {
  background: rgba(238, 61, 90, 0.3);
  border-color: var(--color-crimson);
}

.modal-banner-headline {
  position: absolute;
  bottom: 16px;
  left: 24px;
  right: 24px;
}

.modal-event-title {
  font-family: var(--font-family-display);
  font-size: 26px;
  font-weight: 900;
  color: #FFFFFF;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.modal-venue-date {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: #A0A8BC;
}

/* Scroll Content */
.modal-scroll-content {
  padding: 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
  flex: 1;
}

.modal-section-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.modal-group-heading {
  font-size: 13px;
  font-weight: 700;
  color: #7E8597;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.modal-description-text {
  font-family: var(--font-family-body);
  font-size: 14px;
  line-height: 1.6;
  color: #C2C8D8;
}

/* Lineup */
.modal-lineup-row {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow-x: auto;
  padding: 4px 0;
}

.modal-artist-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 12px;
  border-radius: 9999px;
  flex-shrink: 0;
}

.modal-artist-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
}

.modal-artist-info {
  display: flex;
  flex-direction: column;
}

.artist-name {
  font-size: 13px;
  font-weight: 700;
  color: #FFFFFF;
}

.artist-role {
  font-size: 11px;
  color: #7E8597;
}

/* Ticket Tiers */
.ticket-tiers-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ticket-tier-option {
  display: flex;
  align-items: center;
  gap: 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 14px 18px;
  border-radius: 18px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.ticket-tier-option:hover {
  background: rgba(255, 255, 255, 0.08);
}

.ticket-tier-option.selected {
  background: rgba(0, 66, 217, 0.15);
  border-color: var(--color-royal-blue);
  box-shadow: 0 4px 16px rgba(0, 66, 217, 0.25);
}

.tier-radio-indicator {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
}

.ticket-tier-option.selected .tier-radio-indicator {
  border-color: var(--color-electric-lime);
}

.tier-radio-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-electric-lime);
}

.tier-info-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.tier-name-price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.tier-name {
  font-size: 15px;
  font-weight: 700;
  color: #FFFFFF;
}

.tier-price {
  font-family: var(--font-family-display);
  font-size: 16px;
  font-weight: 800;
  color: var(--color-electric-lime);
}

.tier-perks-sub {
  font-size: 12px;
  color: #8C93A4;
}

/* Quantity Row */
.quantity-row {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.quantity-label {
  font-size: 14px;
  font-weight: 600;
  color: #C2C8D8;
}

.quantity-counter-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.qty-btn {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #FFFFFF;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.qty-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.2);
}

.qty-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.qty-number {
  font-family: var(--font-family-mono);
  font-size: 16px;
  font-weight: 700;
  color: #FFFFFF;
  min-width: 24px;
  text-align: center;
}

/* Price Breakdown Card */
.modal-price-breakdown-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: rgba(0, 0, 0, 0.35);
  padding: 14px 18px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.breakdown-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: #7E8597;
}

.breakdown-line.total-line {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 8px;
  color: #FFFFFF;
  font-weight: 700;
  font-size: 15px;
}

.total-highlight {
  font-family: var(--font-family-display);
  font-size: 18px;
  color: var(--color-electric-lime);
}

/* Checkout Footer */
.modal-checkout-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 24px;
  background: #141722;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.checkout-total-col {
  display: flex;
  flex-direction: column;
}

.checkout-label {
  font-size: 11px;
  color: #7E8597;
  text-transform: uppercase;
  font-weight: 600;
}

.checkout-big-price {
  font-family: var(--font-family-display);
  font-size: 24px;
  font-weight: 900;
  color: #FFFFFF;
}

.modal-confirm-checkout-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--color-brand-saffron);
  color: #FFFFFF;
  border: none;
  padding: 14px 26px;
  border-radius: 9999px;
  font-family: var(--font-family-display);
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 4px 18px rgba(224, 122, 40, 0.35);
  transition: all 0.2s ease;
}

.modal-confirm-checkout-btn:hover {
  background: var(--color-brand-saffron-hover);
  box-shadow: 0 8px 24px rgba(224, 122, 40, 0.5);
}

.modal-confirm-checkout-btn:disabled {
  opacity: 0.7;
  cursor: wait;
}

/* Mobile Responsive */
@media (max-width: 768px) {
  .event-modal-backdrop {
    padding: 0;
    align-items: flex-end;
    z-index: 2000;
  }
  .event-modal-card {
    max-width: 100%;
    border-radius: 24px 24px 0 0;
    max-height: 90vh;
    border-bottom: none;
  }
  .modal-banner-art {
    height: 140px;
  }
  .modal-close-btn {
    top: 14px;
    right: 14px;
    width: 32px;
    height: 32px;
  }
  .modal-body-scroll {
    padding: 16px 16px 24px 16px;
    gap: 16px;
  }
  .modal-title {
    font-size: 22px;
    letter-spacing: -0.4px;
  }
  .modal-date-venue-row {
    font-size: 12px;
  }
  .modal-artist-chips-row {
    gap: 8px;
  }
  .modal-artist-chip {
    padding: 6px 12px;
  }
  .ticket-tier-option {
    padding: 12px 14px;
    gap: 10px;
  }
  .tier-name {
    font-size: 13px;
  }
  .tier-price {
    font-size: 14px;
  }
  .tier-desc {
    font-size: 11px;
  }
  .modal-checkout-footer {
    padding: 14px 16px max(14px, env(safe-area-inset-bottom)) 16px;
  }
  .checkout-big-price {
    font-size: 20px;
  }
  .modal-confirm-checkout-btn {
    padding: 12px 18px;
    font-size: 13px;
    gap: 6px;
  }
}

