import React, { useState, useMemo } from 'react';
import { motion } from 'motion/react';
import AppIcon from '../common/AppIcon';
import './EventCatalog.css';

export default function EventCatalog({
  events = [],
  genres = [],
  selectedCity = 'Bengaluru, Koramangala',
  searchQuery = '',
  onSelectEvent = () => {},
  onBookNow = () => {},
  onToggleFavorite = () => {},
  favorites = []
}) {
  const [selectedGenre, setSelectedGenre] = useState('all');
  const [sortBy, setSortBy] = useState('trending');

  // Filter & sort logic
  const filteredEvents = useMemo(() => {
    return events.filter(e => {
      // Search match
      const q = searchQuery.toLowerCase().trim();
      const matchesSearch = !q || 
        e.title.toLowerCase().includes(q) || 
        e.category.toLowerCase().includes(q) || 
        e.venue.toLowerCase().includes(q) ||
        e.description.toLowerCase().includes(q);

      // Genre match
      const matchesGenre = selectedGenre === 'all' || e.genre === selectedGenre;

      return matchesSearch && matchesGenre;
    }).sort((a, b) => {
      if (sortBy === 'price-asc') return a.price - b.price;
      if (sortBy === 'price-desc') return b.price - a.price;
      return 0; // default trending
    });
  }, [events, searchQuery, selectedGenre, sortBy]);

  return (
    <section className="web-catalog-section" id="events-catalog">
      <div className="catalog-container">
        
        {/* Section Header & Subtitle */}
        <div className="catalog-header-row">
          <div>
            <div className="section-eyebrow-pill">
              <AppIcon name="ticket" size={13} color="var(--color-brand-saffron)" />
              <span>Verified Live Access</span>
            </div>
            <h2 className="section-title">Explore Experiences</h2>
            <p className="section-subtitle">
              Instant digital screen passes with encrypted dynamic barcodes and zero gate wait times.
            </p>
          </div>

          {/* Quick Sort Dropdown */}
          <div className="catalog-sort-wrap">
            <span className="sort-label">Sort:</span>
            <select 
              value={sortBy} 
              onChange={(e) => setSortBy(e.target.value)}
              className="catalog-sort-select"
            >
              <option value="trending">Trending First</option>
              <option value="price-asc">Price: Low to High</option>
              <option value="price-desc">Price: High to Low</option>
            </select>
          </div>
        </div>

        {/* Genre Category Pills (Zero Emojis) */}
        <div className="genre-filter-scroller">
          {genres.map(g => (
            <button
              key={g.id}
              className={`genre-pill-btn ${selectedGenre === g.id ? 'active' : ''}`}
              onClick={() => setSelectedGenre(g.id)}
            >
              <span className="genre-label">{g.label}</span>
            </button>
          ))}
        </div>

        {/* Results Counter Bar */}
        <div className="results-status-bar">
          <span className="results-count-text">
            Showing <strong className="count-number">{filteredEvents.length}</strong> events in <strong>{selectedCity}</strong>
          </span>
          {searchQuery && (
            <span className="search-filter-tag">
              Matching: "{searchQuery}"
            </span>
          )}
        </div>

        {/* Event Cards Grid */}
        {filteredEvents.length > 0 ? (
          <div className="events-responsive-grid">
            {filteredEvents.map(event => {
              const isFav = favorites.includes(event.id);
              return (
                <motion.article 
                  key={event.id}
                  className="catalog-event-card"
                  onClick={() => onSelectEvent(event)}
                  whileHover={{ y: -5, transition: { duration: 0.2 } }}
                  whileTap={{ scale: 0.99 }}
                >
                  {/* Card Media Header */}
                  <div className="card-media-wrap">
                    <img src={event.image} alt={event.title} className="card-media-img" />
                    <div className="card-media-dark-vignette"></div>

                    {/* Category Chip */}
                    <div className="card-top-category-pill">
                      <AppIcon name="music" size={11} color="var(--color-brand-saffron)" />
                      <span>{event.category}</span>
                    </div>

                    {/* Heart Button */}
                    <button 
                      className={`card-heart-btn ${isFav ? 'active' : ''}`}
                      onClick={(e) => {
                        e.stopPropagation();
                        onToggleFavorite(event.id);
                      }}
                      title={isFav ? 'Remove from saved' : 'Save event'}
                      aria-label="Save event"
                    >
                      <AppIcon 
                        name="heart" 
                        size={16} 
                        color={isFav ? '#E05342' : '#FFFFFF'} 
                        fill={isFav ? '#E05342' : 'none'}
                        strokeWidth={2}
                      />
                    </button>
                  </div>

                  {/* Card Body */}
                  <div className="card-body-content">
                    {/* Date & Venue Row */}
                    <div className="card-date-venue-row">
                      <span className="card-date-badge">
                        <AppIcon name="calendar" size={12} color="var(--color-muted-gray)" />
                        {event.date}
                      </span>
                      <span className="card-venue-text" title={event.venue}>
                        <AppIcon name="pin" size={12} color="var(--color-muted-gray)" />
                        <span>{event.venueShort || event.venue}</span>
                      </span>
                    </div>

                    {/* Event Title */}
                    <h3 className="card-event-title">{event.title}</h3>

                    {/* Short Description */}
                    <p className="card-brief-desc">{event.description}</p>

                    {/* Card Footer: Price & Book CTA */}
                    <div className="card-footer-row">
                      <div className="card-price-block">
                        <span className="price-prefix">From</span>
                        <span className="price-bold">${event.price.toFixed(2)}</span>
                      </div>

                      <div className="card-action-group">
                        <button 
                          className="card-book-btn"
                          onClick={(e) => {
                            e.stopPropagation();
                            onBookNow(event);
                          }}
                        >
                          Book Now
                        </button>
                        <button 
                          className="card-lime-arrow-btn"
                          aria-label={`View details for ${event.title}`}
                        >
                          <AppIcon name="arrow-up-right" size={15} color="#FFFFFF" strokeWidth={2.2} />
                        </button>
                      </div>
                    </div>
                  </div>
                </motion.article>
              );
            })}
          </div>
        ) : (
          <div className="catalog-empty-state">
            <AppIcon name="search" size={28} color="var(--color-muted-gray)" />
            <h3 className="empty-title">No events found</h3>
            <p className="empty-desc">
              We couldn't find any events matching your search or filters in {selectedCity}.
            </p>
            <button 
              className="empty-reset-btn"
              onClick={() => {
                setSelectedGenre('all');
              }}
            >
              Reset Filters
            </button>
          </div>
        )}

      </div>
    </section>
  );
}

src\\components\\web\\EventCatalog.css.text:
.web-catalog-section {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 36px 24px 60px;
}

.catalog-container {
  width: 100%;
}

/* Header Row */
.catalog-header-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.section-eyebrow-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-brand-saffron);
  background: rgba(224, 122, 40, 0.08);
  border: 1px solid rgba(224, 122, 40, 0.25);
  padding: 5px 12px;
  border-radius: 9999px;
  margin-bottom: 8px;
}

.section-title {
  font-family: var(--font-family-display);
  font-size: 36px;
  font-weight: 900;
  letter-spacing: -0.03em;
  color: #FFFFFF;
  margin-bottom: 6px;
}

.section-subtitle {
  font-family: var(--font-family-body);
  font-size: 15px;
  color: #8C93A4;
  max-width: 580px;
}

/* Sort Dropdown */
.catalog-sort-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 6px 14px;
  border-radius: 12px;
}

.sort-label {
  font-size: 12px;
  font-weight: 600;
  color: #7E8597;
}

.catalog-sort-select {
  background: transparent;
  border: none;
  color: #FFFFFF;
  font-family: var(--font-family-body);
  font-size: 13px;
  font-weight: 600;
  outline: none;
  cursor: pointer;
}

.catalog-sort-select option {
  background: #14161F;
  color: #FFFFFF;
}

/* Genre Filter Pills Scroller */
.genre-filter-scroller {
  display: flex;
  align-items: center;
  gap: 10px;
  overflow-x: auto;
  padding: 4px 0 16px;
  margin-bottom: 16px;
  scrollbar-width: thin;
}

.genre-pill-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #C2C8D8;
  padding: 10px 18px;
  border-radius: 9999px;
  font-family: var(--font-family-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.genre-pill-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #FFFFFF;
  border-color: rgba(255, 255, 255, 0.2);
}

.genre-pill-btn.active {
  background: var(--color-brand-saffron);
  color: #FFFFFF;
  border-color: var(--color-brand-saffron);
  font-weight: 600;
  box-shadow: 0 4px 14px rgba(224, 122, 40, 0.3);
}

/* Results Status Bar */
.results-status-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: #7E8597;
  margin-bottom: 24px;
}

.count-number {
  color: #FFFFFF;
}

.search-filter-tag {
  background: rgba(0, 66, 217, 0.2);
  border: 1px solid rgba(0, 66, 217, 0.4);
  color: #80B0EC;
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 12px;
}

/* Events Responsive Grid */
.events-responsive-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* Event Card */
.catalog-event-card {
  background: rgba(41, 37, 34, 0.76);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(245, 240, 232, 0.12);
  border-radius: 24px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.25s ease;
}

.catalog-event-card:hover {
  transform: translateY(-4px);
  border-color: rgba(255, 130, 72, 0.5);
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.6), 0 0 24px rgba(255, 130, 72, 0.2);
}

/* Card Media */
.card-media-wrap {
  position: relative;
  width: 100%;
  height: 220px;
  overflow: hidden;
}

.card-media-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s cubic-bezier(0.19, 1, 0.22, 1);
}

.catalog-event-card:hover .card-media-img {
  transform: scale(1.06);
}

.card-media-dark-vignette {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(8, 8, 8, 0.2) 0%,
    rgba(17, 20, 30, 0.95) 100%
  );
}

.card-top-category-pill {
  position: absolute;
  top: 14px;
  left: 14px;
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(8, 8, 8, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(10px);
  padding: 5px 12px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  color: #FFFFFF;
}

.card-heart-btn {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(8, 8, 8, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.18);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: transform 0.2s ease, background 0.2s ease;
}

.card-heart-btn:hover {
  transform: scale(1.1);
  background: rgba(8, 8, 8, 0.85);
}

.card-heart-btn.active {
  background: rgba(238, 61, 90, 0.25);
  border-color: var(--color-crimson);
}

/* Card Body */
.card-body-content {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.card-date-venue-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  margin-bottom: 8px;
}

.card-date-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #9AA2B6;
  font-weight: 600;
}

.card-venue-text {
  color: #7E8597;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.card-event-title {
  font-family: var(--font-family-display);
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #FFFFFF;
  margin-bottom: 8px;
  line-height: 1.25;
}

.card-brief-desc {
  font-family: var(--font-family-body);
  font-size: 13px;
  line-height: 1.5;
  color: #8C93A4;
  margin-bottom: 20px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Card Footer */
.card-footer-row {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 16px;
}

.card-price-block {
  display: flex;
  flex-direction: column;
}

.price-prefix {
  font-size: 11px;
  color: #7E8597;
  text-transform: uppercase;
  font-weight: 600;
}

.price-bold {
  font-family: var(--font-family-display);
  font-size: 20px;
  font-weight: 800;
  color: #FFFFFF;
}

.card-action-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.card-book-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #FFFFFF;
  padding: 8px 16px;
  border-radius: 9999px;
  font-family: var(--font-family-body);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.card-book-btn:hover {
  background: var(--color-brand-saffron);
  border-color: var(--color-brand-saffron);
  box-shadow: 0 4px 14px rgba(224, 122, 40, 0.35);
}

.card-lime-arrow-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-brand-saffron);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card-lime-arrow-btn:hover {
  transform: scale(1.08);
  box-shadow: 0 4px 14px rgba(224, 122, 40, 0.45);
}

/* Empty State */
.catalog-empty-state {
  text-align: center;
  padding: 60px 20px;
  background: #11141E;
  border: 1px dashed rgba(255, 255, 255, 0.15);
  border-radius: 24px;
}

.empty-emoji {
  font-size: 40px;
  display: block;
  margin-bottom: 12px;
}

.empty-title {
  font-family: var(--font-family-display);
  font-size: 20px;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 8px;
}

.empty-desc {
  font-size: 14px;
  color: #7E8597;
  max-width: 400px;
  margin: 0 auto 20px;
}

.empty-reset-btn {
  background: var(--color-electric-lime);
  color: #080808;
  border: none;
  padding: 10px 20px;
  border-radius: 9999px;
  font-weight: 700;
  cursor: pointer;
}

/* Responsive */
@media (max-width: 1100px) {
  .events-responsive-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .web-catalog-section {
    padding: 16px 14px 40px 14px;
  }
  .catalog-header-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
  .section-title {
    font-size: 24px;
    letter-spacing: -0.4px;
    margin-bottom: 4px;
  }
  .section-subtitle {
    font-size: 13px;
    line-height: 1.4;
  }
  .catalog-sort-wrapper {
    width: 100%;
    justify-content: space-between;
    background: rgba(255, 255, 255, 0.05);
    padding: 8px 12px;
    border-radius: 12px;
  }
  .genre-filter-scroller {
    margin: 0 -14px 14px -14px;
    padding: 4px 14px 12px 14px;
    gap: 8px;
  }
  .genre-pill-btn {
    padding: 8px 14px;
    font-size: 12px;
    gap: 6px;
  }
  .events-responsive-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .card-media-wrap {
    height: 190px;
  }
  .card-body-content {
    padding: 14px 16px 16px 16px;
    gap: 10px;
  }
  .card-event-title {
    font-size: 18px;
    line-height: 1.25;
  }
  .card-bottom-action-row {
    padding-top: 10px;
  }
  .card-book-cta-btn {
    padding: 10px 16px;
    font-size: 13px;
  }
}

src\\components\\ticket\\TicketCard.css.text:
.hyper-ticket-container {
  display: inline-block;
  position: relative;
  width: 100%;
  max-width: 320px;
  filter: drop-shadow(0 14px 30px rgba(0, 0, 0, 0.12));
}

.hyper-ticket-card {
  background-color: var(--color-pure-white);
  border-radius: 32px;
  padding: 16px 20px 22px 20px;
  color: var(--color-true-black);
  position: relative;
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.04);
}

/* Header Art */
.ticket-header-art {
  width: 100%;
  height: 110px;
  border-radius: 20px;
  overflow: hidden;
  background: #0042D9;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ticket-art-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.hyper-ticket-card:hover .ticket-art-img {
  transform: scale(1.04);
}

/* Title */
.ticket-event-title {
  font-family: var(--font-family-display);
  font-size: 20px;
  font-weight: 700;
  color: #0A0A0A;
  text-align: center;
  margin: 14px 0 12px 0;
  letter-spacing: -0.3px;
}

/* Perforation Divider with Notches */
.ticket-perforation-divider {
  position: relative;
  margin: 12px -20px;
  height: 24px;
  display: flex;
  align-items: center;
}

.ticket-dashed-line {
  width: 100%;
  height: 0;
  border-top: 2px dashed #93A6C8;
  margin: 0 16px;
}

/* Notch Cutouts */
.ticket-notch {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  position: absolute;
  top: 0;
  z-index: 2;
}

.notch-left {
  left: -12px;
}

.notch-right {
  right: -12px;
}

/* Inherit parent background color for realistic hole punched effect */
.bg-blue .ticket-notch {
  background-color: var(--color-royal-blue);
}

.bg-pale .ticket-notch {
  background-color: var(--color-pale-blue-bg);
}

.bg-dark .ticket-notch {
  background-color: var(--color-true-black);
}

/* Metadata Grid */
.ticket-meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  row-gap: 12px;
  column-gap: 16px;
  padding: 6px 4px 6px 4px;
}

.ticket-meta-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.text-right {
  text-align: right;
  align-items: flex-end;
}

.ticket-meta-label {
  font-size: 11px;
  font-weight: 500;
  color: #8C93A4;
  letter-spacing: 0.2px;
}

.ticket-meta-value {
  font-family: var(--font-family-display);
  font-size: 14px;
  font-weight: 700;
  color: #121212;
  letter-spacing: -0.2px;
}

/* Footer & Barcode */
.ticket-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin-top: 4px;
}

.ticket-hash {
  font-family: var(--font-family-mono);
  font-size: 11px;
  font-weight: 500;
  color: #8C93A4;
  letter-spacing: 0.4px;
}

.ticket-barcode-wrap {
  width: 100%;
  padding: 0 8px;
  display: flex;
  justify-content: center;
}

.ticket-barcode-svg {
  width: 100%;
  max-width: 260px;
  height: 48px;
}

