}

.typo-tester-input {
  background: transparent;
  border: none;
  outline: none;
  color: var(--color-pure-white);
  font-family: var(--font-family-display);
  font-size: 15px;
  width: 100%;
}

.typo-reset-btn {
  font-size: 12px;
  color: #9CA3AF;
  text-decoration: underline;
  background: transparent;
  border: none;
  cursor: pointer;
}

@media (max-width: 768px) {
  .behance-slide-typography {
    padding: 32px 20px;
  }
  .typo-table-row {
    grid-template-columns: 1fr 1fr;
    row-gap: 8px;
  }
  .col-size {
    text-align: left;
    padding-right: 0;
  }
}

