import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import MobileFrame from '../mobile/MobileFrame';
import './SlideStudioShowcase.css';

export default function SlideStudioShowcase({ onNavigateHome = () => {} }) {
  // mode: 'studio' (exact Behance render) | 'interactive' (live device simulator)
  const [mode, setMode] = useState('studio');

  return (
    <motion.section 
      className="behance-slide-studio"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.3 }}
    >
      {/* Studio Viewport */}
      <div className="studio-canvas-container">
        {mode === 'studio' ? (
          <div className="studio-render-wrap">
            {/* Authentic Behance Studio Shot with Brutalist Concrete & Tilted iPhone 16 Pro */}
            <motion.div 
              className="studio-mockup-frame"
              whileHover={{ scale: 1.015 }}
              transition={{ type: 'spring', stiffness: 260, damping: 20 }}
            >
              <img 
                src="/assets/kesari_studio.jpg" 
                alt="KESARI Live Studio" 
                className="studio-mockup-img" 
              />

              {/* Click Hotspot over Phone to launch interactive mode */}
              <button 
                className="studio-phone-hotspot"
                onClick={() => setMode('interactive')}
                title="Click to interact with Live Mobile App"
              >
                <div className="hotspot-pulse-badge">
                  <span>Test Mobile Experience</span>
                </div>
              </button>
            </motion.div>
          </div>
        ) : (
          <div className="studio-interactive-wrap">
            <div className="interactive-controls-bar">
              <button 
                className="back-to-studio-btn"
                onClick={() => setMode('studio')}
              >
                ← Back to 3D Studio Mockup
              </button>
              <span className="interactive-badge">Interactive Live Simulator</span>
            </div>
            <MobileFrame initialScreen="home" />
          </div>
        )}
      </div>
    </motion.section>
  );
}

/* Slide 5: 3D Studio Mockup Presentation Board */
.behance-slide-studio {
  width: 100%;
  min-height: 100vh;
  background-color: #000000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  position: relative;
  overflow: hidden;
}

.studio-canvas-container {
  width: 100%;
  max-width: 860px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.studio-render-wrap {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.studio-mockup-frame {
  position: relative;
  width: 100%;
  max-width: 700px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.9);
}

.studio-mockup-img {
  width: 100%;
  height: auto;
  display: block;
}

/* Phone Hotspot */
.studio-phone-hotspot {
  position: absolute;
  top: 10%;
  left: 20%;
  width: 60%;
  height: 80%;
  background: transparent;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

.hotspot-pulse-badge {
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--color-electric-lime);
  color: var(--color-electric-lime);
  font-family: var(--font-family-display);
  font-size: 13px;
  font-weight: 700;
  padding: 8px 18px;
  border-radius: 9999px;
  opacity: 0;
  transform: translateY(10px);
  transition: all 0.3s cubic-bezier(0.19, 1, 0.22, 1);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);
}

.studio-phone-hotspot:hover .hotspot-pulse-badge {
  opacity: 1;
  transform: translateY(0);
}

/* Interactive Simulator Mode */
.studio-interactive-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  width: 100%;
}

.interactive-controls-bar {
  display: flex;
  align-items: center;
  gap: 16px;
}

.back-to-studio-btn {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--color-pure-white);
  padding: 8px 18px;
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.back-to-studio-btn:hover {
  background: rgba(255, 255, 255, 0.2);
  transform: translateX(-2px);
}

.interactive-badge {
  font-size: 12px;
  color: var(--color-electric-lime);
  font-weight: 600;
  letter-spacing: 0.5px;
}

