import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import './SlideColorPalette.css';

export default function SlideColorPalette() {
  const [copiedHex, setCopiedHex] = useState(null);

  const colors = [
    { hex: "#0A0A0A", name: "Obsidian", role: "Primary Deep Canvas & Base Contrast" },
    { hex: "#F5F0E8", name: "Warm ivory", role: "Headlines, Editorial Typography & Crisp Elements" },
    { hex: "#FF8248", name: "Stage orange", role: "Primary CTAs, Active States & Stage Backlight Glow" },
    { hex: "#292522", name: "Charcoal", role: "Card Surfaces, Navigation Bars & Elevated Panels" }
  ];

  const handleCopyHex = (hex) => {
    navigator.clipboard?.writeText?.(hex);
    setCopiedHex(hex);
    setTimeout(() => setCopiedHex(null), 1800);
  };

  return (
    <motion.section 
      className="behance-slide-colors"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.3 }}
    >
      {/* Top Header matching reference */}
      <div className="colors-header">
        <h2 className="colors-title">Color Palette</h2>
        <div className="colors-header-right">
          <div className="colors-thumb-wrap">
            <img src="/assets/kesari_logo.png" alt="KESARI Logo" className="colors-thumb-img" />
          </div>
          <p className="colors-statement">
            A handcrafted luxury palette rooted in Obsidian, Warm Ivory, Stage Orange, and Charcoal for an immersive, tactile live experience.
          </p>
        </div>
      </div>

      {/* Recommended Color Palette Swatch Bar */}
      <div className="palette-swatches-grid">
        {colors.map((c) => (
          <motion.div 
            key={c.hex}
            className="palette-swatch-card"
            whileHover={{ y: -4, scale: 1.02 }}
            onClick={() => handleCopyHex(c.hex)}
            title={`Click to copy ${c.hex}`}
          >
            <div 
              className="palette-swatch-pill" 
              style={{ 
                backgroundColor: c.hex, 
                border: c.hex === '#0A0A0A' ? '1px solid rgba(245, 240, 232, 0.2)' : 'none' 
              }} 
            />
            <div className="palette-swatch-meta">
              <span className="swatch-name">{c.name}</span>
              <span className="swatch-hex font-mono">{c.hex}</span>
              <span className="swatch-role">{c.role}</span>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Main Center Visualization: Pinwheel Donut */}
      <div className="colors-center-stage">
        <motion.div 
          className="pinwheel-container"
          whileHover={{ scale: 1.02 }}
          transition={{ type: 'spring', stiffness: 200, damping: 15 }}
        >
          <img 
            src="/assets/donut_wheel_perfect.png" 
            alt="Color Palette Wheel" 
            className="pinwheel-artwork-img"
          />

          {/* Interactive Clickable Hotspots */}
          <button 
            className="badge-click-hotspot hotspot-lime" 
            onClick={() => handleCopyHex('#FF8248')} 
            title="Click to copy #FF8248 (Stage orange)"
          />
          <button 
            className="badge-click-hotspot hotspot-crimson" 
            onClick={() => handleCopyHex('#FF8248')} 
            title="Click to copy #FF8248"
          />
          <button 
            className="badge-click-hotspot hotspot-sky" 
            onClick={() => handleCopyHex('#F5F0E8')} 
            title="Click to copy #F5F0E8 (Warm ivory)"
          />
          <button 
            className="badge-click-hotspot hotspot-white" 
            onClick={() => handleCopyHex('#292522')} 
            title="Click to copy #292522 (Charcoal)"
          />
        </motion.div>

        {/* Copy Feedback Toast */}
        <AnimatePresence>
          {copiedHex && (
            <motion.div 
              className="color-copied-toast"
              initial={{ opacity: 0, y: 15 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
            >
              <span>Copied <strong>{copiedHex}</strong> to clipboard!</span>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.section>
  );
}

/* Slide 2: Color Palette Presentation Board */
.behance-slide-colors {
  width: 100%;
  min-height: 100vh;
  background-color: #000000;
  color: var(--color-pure-white);
  padding: 40px 60px 60px 60px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  overflow: hidden;
}

/* Header */
.colors-header {
  width: 100%;
  max-width: 1024px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 24px;
  gap: 32px;
}

.colors-title {
  font-family: var(--font-family-display);
  font-size: 44px;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: var(--color-pure-white);
  margin: 0;
  line-height: 1.1;
}

.colors-header-right {
  display: flex;
  align-items: center;
  gap: 20px;
  max-width: 480px;
}

.colors-thumb-wrap {
  width: 56px;
  height: 56px;
  border-radius: 16px;
  overflow: hidden;
  flex-shrink: 0;
  box-shadow: 0 4px 16px rgba(0, 66, 217, 0.4);
}

.colors-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.colors-statement {
  font-family: var(--font-family-body);
  font-size: 13.5px;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.85);
  margin: 0;
  font-weight: 400;
}

/* Swatches Grid */
.palette-swatches-grid {
  width: 100%;
  max-width: 1024px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 18px 0 28px 0;
}

.palette-swatch-card {
  background: #292522;
  border: 1px solid rgba(245, 240, 232, 0.1);
  border-radius: 14px;
  padding: 14px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.palette-swatch-card:hover {
  border-color: #FF8248;
}

.palette-swatch-pill {
  width: 100%;
  height: 52px;
  border-radius: 10px;
}

.palette-swatch-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.swatch-name {
  font-family: var(--font-family-display);
  font-size: 15px;
  font-weight: 700;
  color: #F5F0E8;
}

.swatch-hex {
  font-size: 12px;
  color: #FF8248;
  font-weight: 600;
  letter-spacing: 0.05em;
}

.swatch-role {
  font-size: 11px;
  line-height: 1.4;
  color: #A8A29A;
}

@media (max-width: 768px) {
  .palette-swatches-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
.colors-center-stage {
  width: 100%;
  max-width: 1024px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex-grow: 1;
  position: relative;
  margin-top: 10px;
}

.pinwheel-container {
  position: relative;
  width: 100%;
  max-width: 600px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pinwheel-artwork-img {
  width: 100%;
  height: auto;
  display: block;
  filter: drop-shadow(0 20px 50px rgba(0, 0, 0, 0.8));
}

/* Hotspots */
.badge-click-hotspot {
  position: absolute;
  background: transparent;
  border: none;
  cursor: pointer;
  border-radius: 9999px;
  width: 120px;
  height: 48px;
}

.hotspot-lime {
  top: 13%;
  left: 0;
}

.hotspot-crimson {
  top: 4%;
  right: 18%;
}

.hotspot-sky {
  bottom: 18%;
  right: 10%;
}

.hotspot-white {
  bottom: 8%;
  left: 10%;
}

.badge-click-hotspot:hover {
  outline: 1.5px solid rgba(255, 255, 255, 0.4);
  background: rgba(255, 255, 255, 0.05);
}

/* Toast */
.color-copied-toast {
  position: absolute;
  bottom: 24px;
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 10px 20px;
  border-radius: 9999px;
  color: #FFFFFF;
  font-size: 13px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5);
}

.color-copied-toast strong {
  color: var(--color-electric-lime);
}

@media (max-width: 768px) {
  .behance-slide-colors {
    padding: 32px 20px;
  }
  .colors-header {
    flex-direction: column;
    gap: 16px;
  }
  .colors-header-right {
    flex-direction: column;
    align-items: flex-start;
  }
}

