 async function feature(event){setBusy(true);setError('');try{await api('/api/admin/events/'+event.id,{method:'PUT',body:JSON.stringify({...event,featured:!event.featured})});await load();announceContentChange();setNotice(event.featured?'Feature removed. Date order applies.':'Event featured on the landing carousel.')}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function saveSettings(e){e.preventDefault();setBusy(true);setError('');try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});await load();announceContentChange();setNotice('Payment and contact settings saved.')}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function review(order,status){if(!window.confirm(status==='confirmed'?`Have you verified ${money(order.amount)} with transaction ${order.utr} in your bank account?`:'Reject this booking? Any refund must be arranged separately.'))return;setBusy(true);setError('');try{await api('/api/admin/orders/'+order.id+'/review',{method:'POST',body:JSON.stringify({status})});await load();announceContentChange();setNotice(status==='confirmed'?'Confirmed. The guest can now retrieve their ticket.':'Booking declined. Arrange any required refund separately.')}catch(e){setError(e.message)}finally{setBusy(false)}}
 if(!data)return <div className="admin-login-page"><a className="admin-home" href="#/"><img src="/assets/kesari-logo.png" alt="Kesari — The Memory Studio"/></a><form className="admin-login-card" onSubmit={login}><span className="memory-overline">JUST FOR THE TEAM</span><h1>Welcome back.</h1><p>Manage events, the landing carousel and guest bookings.</p><label>Admin password<input name="password" type="password" required autoComplete="current-password"/></label>{error&&<p className="booking-error" role="alert">{error}</p>}<button className="memory-action" disabled={busy}>{busy?'Signing in…':'Sign in'}<ArrowUpRight size={17}/></button><a href="#/">← Back to Kesari</a></form></div>;
 const landing=selectLandingEvents(data.events),visible=data.events.filter(e=>e.title.toLowerCase().includes(filter.toLowerCase()));
 return <div className="admin-console"><header><a className="admin-home" href="#/"><img src="/assets/kesari-logo.png" alt="Kesari"/><span>TEAM SPACE</span></a><a href="#/" target="_blank" rel="noreferrer">View website <ArrowUpRight size={15}/></a><button onClick={async()=>{await api('/api/admin/logout',{method:'POST'});setData(null)}}><LogOut size={16}/>Sign out</button></header><div className="admin-console-body"><nav aria-label="Admin sections">{['Events','Bookings','Settings'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>{setTab(t);setEdit(null);setError('');setNotice('')}}>{t}</button>)}</nav><main><div className="admin-title-row"><div><p className="memory-overline">KESARI · KEEP IT SIMPLE</p><h1>{tab==='Events'?'Make good things happen.':tab==='Bookings'?'Every guest, one place.':'The essentials.'}</h1></div>{tab==='Events'&&!edit&&<button className="memory-action" onClick={()=>setEdit(blankEvent())}><Plus size={17}/>Add event</button>}</div>{error&&<p className="booking-error" role="alert">{error}</p>}{notice&&<p className="admin-notice" role="status"><Check size={16}/>{notice}</p>}
 {tab==='Events'&&(edit?<form className="admin-editor" onSubmit={saveEvent} key={edit.id}><h2>{edit.title?'Edit event':'New event'}</h2><div className="admin-fields"><label>Event title<input name="title" defaultValue={edit.title} required maxLength={120}/></label><label>Date & time (India)<input name="date" type="datetime-local" defaultValue={localTime(edit.date)} required/></label><label>Ticket price (₹)<input name="price" type="number" min="1" max="100000" step="0.01" defaultValue={edit.price??''} placeholder="Leave blank until decided"/></label><label>Guest capacity<input name="capacity" type="number" min="1" max="2000" defaultValue={edit.capacity} required/></label><label>Category<select name="category" defaultValue={edit.category}>{['Music','Workshops','Community'].map(x=><option key={x}>{x}</option>)}</select></label><label>Event photo<select name="image" defaultValue={edit.image}>{['music','workshop','community','hall','ev_rock','ev_jazz','ev_sukoon','ev_pottery','ev_openmic'].map(x=><option key={x}>{x}</option>)}</select></label><label>Custom event image URL<input name="imageUrl" defaultValue={edit.imageUrl||''} placeholder="https://… or /assets/…"/></label><label>Landing artwork URL<input name="landingImage" defaultValue={edit.landingImage||''} placeholder="Blank uses the event photo"/></label><p className="admin-hint admin-full">The photo carousel uses the event photo by default. Set a landing artwork URL for a different poster. Glass menu cards always remain navigation.</p><label className="admin-full">Description<textarea name="description" defaultValue={edit.description} maxLength={3000}/></label><label>Booking method<select name="bookingMode" defaultValue={edit.bookingMode}><option value="upi">UPI · manual verification</option><option value="external">External booking provider</option></select></label><label>External booking URL<input name="externalUrl" type="url" defaultValue={edit.externalUrl} placeholder="https://…"/></label><label className="admin-full">Booking & refund terms<textarea name="terms" defaultValue={edit.terms} maxLength={2000}/></label><label>Featured priority<input name="featureOrder" type="number" min="0" max="999" defaultValue={edit.featureOrder||0}/><small>Lower numbers appear first among featured events.</small></label><div/><label className="admin-check"><input type="checkbox" name="published" defaultChecked={edit.published}/>Published</label><label className="admin-check"><input type="checkbox" name="bookingOpen" defaultChecked={edit.bookingOpen}/>Bookings open</label><label className="admin-check"><input type="checkbox" name="featured" defaultChecked={edit.featured}/>Featured on landing</label><label className="admin-check"><input type="checkbox" name="showOnLanding" defaultChecked={edit.showOnLanding!==false}/>Include in landing carousel</label></div><p className="admin-hint">Only published future events appear on the landing page. Featured events come first, followed by the nearest dates. Hiding an event from the landing does not unpublish its booking page.</p><div className="admin-actions"><button className="memory-action" disabled={busy}>{busy?'Saving…':'Save event'}<Check size={17}/></button><button type="button" onClick={()=>setEdit(null)}>Cancel</button></div></form>:<><section className="admin-landing-order"><h2>Landing carousel order</h2><p>{landing.length?landing.map((e,i)=>`${i+1}. ${e.title}${e.featured?' ★':''}`).join('  →  '):'No upcoming events. Add or publish one to show it on the blue screen.'}</p><small>Nearest upcoming date by default. Feature an event to place it ahead of the date order.</small></section><input className="admin-search" aria-label="Search managed events" placeholder="Search your events…" value={filter} onChange={e=>setFilter(e.target.value)}/><div className="admin-event-list">{visible.map(e=><article key={e.id} data-event-id={e.id}><img src={eventImage(e)} alt=""/><div><span className="admin-status">{e.published?'Published':'Draft'}{e.featured?' · Featured':''}</span><h2>{e.title}</h2><p>{dateLabel(e.date)} · {e.price==null?'Price not set':money(e.price)}</p><small>{e.bookingOpen?'Bookings open':'Bookings closed'} · {e.capacity} capacity</small></div><div className="admin-actions"><button className="admin-star" aria-pressed={!!e.featured} disabled={busy} onClick={()=>feature(e)}><Star size={17} fill={e.featured?'currentColor':'none'}/>{e.featured?'Unfeature':'Feature'}</button><button className="memory-action" onClick={()=>setEdit(e)}>Edit<ArrowUpRight size={16}/></button></div></article>)}</div></>)}
 {tab==='Settings'&&<form className="admin-editor" onSubmit={saveSettings}><h2>UPI & contact</h2><p className="admin-hint">Set the exact payee name displayed by your merchant UPI app before opening direct bookings.</p><div className="admin-fields"><label>UPI ID<input name="upiId" defaultValue={data.settings.upiId} required/></label><label>Verified payee name<input name="payeeName" defaultValue={data.settings.payeeName}/></label><label>Email<input name="email" type="email" defaultValue={data.settings.email} required/></label><label>Phone<input name="phone" type="tel" defaultValue={data.settings.phone} required/></label></div><button className="memory-action" disabled={busy}>Save settings<Check size={17}/></button></form>}
 {tab==='Bookings'&&<><div className="admin-booking-tools"><p className="admin-hint">Check the transaction in your merchant app before confirming. Confirmation creates a ticket; refunds are handled separately.</p><button className="memory-action" onClick={()=>load().catch(e=>setError(e.message))}><RefreshCw size={15}/>Refresh</button></div>{!data.orders.length?<div className="memory-empty"><h2>No bookings yet.</h2></div>:data.orders.map(o=><article className="admin-booking" key={o.id} data-order-id={o.id}><span className="admin-status">{o.status.replaceAll('_',' ')}</span><h2>{o.eventTitle}</h2><p>{o.name} · {o.quantity} guest(s) · {money(o.amount)}</p><p>{o.email} · {o.phone}</p><small>{o.reference} · UPI transaction: {o.utr||'Not submitted'}</small>{o.status==='pending_review'&&<div className="admin-actions"><button className="memory-action" disabled={busy} onClick={()=>review(o,'confirmed')}>Verify & confirm</button><button disabled={busy} onClick={()=>review(o,'rejected')}>Decline</button></div>}</article>)}</>}
 </main></div></div>
}

