/* QR Code Scanner Modal */
.qr-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  animation: fadeIn 0.25s ease;
}

.qr-modal-sheet {
  background: var(--color-pure-white);
  color: var(--color-true-black);
  width: 100%;
  max-width: 420px;
  border-radius: 28px;
  padding: 24px 28px 28px 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  animation: scaleInModal 0.28s cubic-bezier(0.19, 1, 0.22, 1);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
}

/* Mobile simulator inner frame override */
.mobile-canvas-inner .qr-modal-backdrop {
  position: absolute;
  align-items: flex-end;
  padding: 0;
}

.mobile-canvas-inner .qr-modal-sheet {
  border-radius: 32px 32px 0 0;
