  transition: transform 0.6s ease;
}

.onboarding-img-gradient-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 40%,
    rgba(0, 62, 204, 0.4) 75%,
    rgba(0, 62, 204, 0.95) 100%
  );
}

.onboarding-floating-pill {
  position: absolute;
  bottom: 16px;
