  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 9999px;
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-pure-white);
}

/* Bottom Content */
.onboarding-bottom-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  z-index: 5;
}

.onboarding-heading {
