  font-weight: 700;
  letter-spacing: -0.8px;
  color: var(--color-pure-white);
  line-height: 1.15;
  margin: 0;
}

.onboarding-description {
  font-size: 14px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.82);
  margin: 0;
}

/* Translucent Card */
.onboarding-translucent-card {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(14px);
  border-radius: 18px;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  color: var(--color-pure-white);
  margin-top: 4px;
}

/* Footer Controls */
.onboarding-footer-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
}

.onboarding-circle-btn {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.18);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.onboarding-circle-btn:hover:not(.disabled) {
  background: rgba(255, 255, 255, 0.25);
  transform: scale(1.08);
}

.onboarding-circle-btn.disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.onboarding-dots-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.onboarding-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.35);
  transition: width 0.25s ease, background-color 0.25s ease;
}

.onboarding-dot.active {
  width: 22px;
  border-radius: 9999px;
  background: var(--color-electric-lime);
  box-shadow: 0 0 10px var(--color-lime-glow);
}

/* Electric Lime Next Button */
.onboarding-lime-action-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-electric-lime);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lime);
  transition: transform var(--transition-fast), filter var(--transition-fast);
}

.onboarding-lime-action-btn:hover {
  transform: scale(1.08);
  filter: brightness(1.06);
}

