/* Mobile Frame Container */
.mobile-frame-showcase {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  width: 100%;
}

/* Screen Switcher Bar */
.frame-screen-switcher {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #12141D;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  padding: 6px 14px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  flex-wrap: wrap;
  justify-content: center;
}

.switcher-label {
  font-size: 12px;
  font-weight: 600;
  color: #9CA3AF;
  margin-right: 4px;
}

.switch-tab-btn {
  background: transparent;
  color: #D1D5DB;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 9999px;
  transition: all var(--transition-fast);
}

.switch-tab-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--color-pure-white);
}

.switch-tab-btn.active {
  background: var(--color-electric-lime);
