}

/* iPhone Chassis */
.iphone-outer-chassis {
  position: relative;
  width: 380px;
  height: 790px;
  background: #1A1B22;
  border-radius: 54px;
  padding: 12px;
  box-shadow: 
    0 0 0 2px #383A48,
    0 0 0 6px #101116,
    0 30px 80px rgba(0, 0, 0, 0.65),
    0 10px 30px rgba(0, 66, 217, 0.15);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Dynamic Island */
.iphone-dynamic-island {
  position: absolute;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 110px;
  height: 30px;
  background: #000000;
  border-radius: 20px;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.island-camera-lens {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #111424;
  border: 1px solid #1E2238;
}

/* Status Bar */
.iphone-status-bar {
  position: absolute;
  top: 18px;
  left: 28px;
  right: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  z-index: 45;
  color: #000000;
  font-size: 13px;
  font-weight: 700;
  pointer-events: none;
}

.status-time {
  letter-spacing: -0.2px;
}

.status-icons {
  display: flex;
  align-items: center;
  gap: 6px;
}

.battery-indicator-wrap {
  width: 22px;
  height: 11px;
  border: 1.5px solid currentColor;
  border-radius: 3.5px;
  padding: 1.5px;
  position: relative;
}

.battery-indicator-wrap::after {
  content: '';
  position: absolute;
  right: -3px;
  top: 3px;
  width: 1.5px;
  height: 3px;
  background: currentColor;
  border-radius: 0 1px 1px 0;
}

.battery-level-bar {
  width: 80%;
  height: 100%;
  background: currentColor;
  border-radius: 1px;
}

/* Screen Viewport */
.iphone-screen-viewport {
  width: 100%;
  height: 100%;
  border-radius: 44px;
  overflow: hidden;
  position: relative;
  background: var(--color-pale-blue-bg);
}

/* Bottom Home Indicator */
.iphone-home-indicator {
  position: absolute;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  width: 130px;
  height: 4px;
  border-radius: 9999px;
  background: rgba(0, 0, 0, 0.85);
  z-index: 50;
  pointer-events: none;
}

/* Responsive phone preview */
.standalone-mobile-canvas {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 30px 16px 80px 16px;
  width: 100%;
}

.frame-screen-switcher {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #12141D;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  padding: 6px 12px;
  margin-bottom: 24px;
  max-width: calc(100vw - 32px);
  overflow-x: auto;
  scrollbar-width: none;
}

@media (max-width: 480px) {
  .iphone-outer-chassis {
    width: 340px;
    height: 700px;
    border-radius: 44px;
    padding: 10px;
  }
  .iphone-screen-viewport {
    border-radius: 36px;
  }
}

