/* Customer screens share the landing's frame, compact header and glass surfaces. */
.kesari-app.studio-screen{--studio-muted:#c5d2e3;--studio-line:#ffffff29;width:100%;height:100%;min-height:0;position:relative;isolation:isolate;overflow:clip;border-radius:47px;container-type:inline-size;background:#10243b;color:white;font-family:var(--font-family-display)}
.studio-backdrop{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:blur(16px);transform:scale(1.1);pointer-events:none}
.studio-backdrop-wash{position:absolute;inset:0;background:linear-gradient(160deg,#081a35ce,#073366b8 55%,#294a71e6);pointer-events:none}
.studio-content{position:absolute;z-index:2;inset:18% 0 12%;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#ffffff30 transparent;padding:0 5cqw 24px;animation:studio-page-enter .2s ease}
.studio-screen .memory-page{max-width:none;min-height:0;margin:0;padding:0;color:white;font-family:inherit}
.studio-screen .memory-page-heading{gap:12px;margin:0 0 22px;align-items:flex-start}
.studio-screen .memory-page-heading>div{min-width:0;flex:1}
