.studio-screen .memory-event-top>button{width:38px;height:38px;backdrop-filter:blur(15px)}
.studio-screen .memory-event-open{bottom:11px;left:11px;right:11px;width:calc(100% - 22px);padding:17px;border-radius:23px;border:1px solid #ffffff29;background:linear-gradient(135deg,#cfdef83b,#24396470);backdrop-filter:blur(20px)}
