.studio-screen .memory-empty h2{font:500 25px/1.1 var(--font-family-display);letter-spacing:-.5px}
.studio-screen .memory-empty p,.studio-screen .memory-muted{color:var(--studio-muted);font-size:11px!important;line-height:1.8}
