.studio-screen .booking-terms,.studio-screen .booking-notice{color:#d6e4f8;background:#ffffff0c;border:1px solid #ffffff1f;border-radius:16px;padding:13px;font-size:11px;overflow-wrap:anywhere}
.studio-screen .booking-error{color:#ffe0e8;background:#9c28504d;border:1px solid #ff9ab940;font-size:12px;border-radius:16px}
.studio-screen .booking-consent input{width:17px;height:17px;margin:2px 0 0;padding:0;flex-shrink:0}
.studio-screen .payment-qr{background:white;padding:10px;border-radius:20px;width:224px;height:224px;max-width:100%;margin:22px auto;object-fit:contain}
.payment-code{width:230px;max-width:100%;aspect-ratio:1;display:grid;place-items:center;margin:20px auto}
.studio-screen .payment-code{width:224px;margin:22px auto}
.studio-screen .payment-code>.payment-qr{margin:0;width:100%;height:100%}
.studio-screen .booking-success-icon{color:#172221}
.studio-screen .live-tickets-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:20px;margin-top:20px}
.studio-screen .live-ticket{position:relative;padding:20px;border-radius:27px;background:#f9fbff;color:#14243b;border:1px solid white;box-shadow:0 12px 30px #07142a33}
.studio-screen .live-ticket::before,.studio-screen .live-ticket::after{content:'';position:absolute;top:144px;width:20px;height:20px;border-radius:50%;background:#284e72}
.studio-screen .live-ticket::before{left:-10px}.studio-screen .live-ticket::after{right:-10px}
.studio-screen .live-ticket .memory-overline{color:#60728c;font-size:8px}
