import React,{useEffect,useRef,useState} from 'react';
import QRCode from 'qrcode';
import {ArrowUpRight,ArrowLeft,Search,CalendarDays,MapPin,Heart,Ticket,Check,RefreshCw,Printer} from 'lucide-react';
import {api} from '../../lib/api';
import {createRequestKey} from '../../lib/identifiers';
import {dateLabel,timeLabel,money,eventImage} from '../../lib/events';
import {PageHeader} from '../pages/MemoryPages';
import './EventPages.css';

const revealBooking = element => element?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});

export function CodeImage({value}){const[src,setSrc]=useState('');useEffect(()=>{let live=true;QRCode.toDataURL(value,{width:260,margin:2,errorCorrectionLevel:'M'}).then(src=>{if(live)setSrc(src)}).catch(()=>{if(live)setSrc('')});return()=>{live=false}},[value]);return <div className="payment-code" aria-busy={!src}>{src?<img className="payment-qr" src={src} alt="QR code"/>:<p className="memory-muted" role="status">Preparing QR code…</p>}</div>}

export function EventList({events,saved,onSave,onSelect,onHome,loading,error,discover=false}){
 const[search,setSearch]=useState(''),[filter,setFilter]=useState('All');
 const visible=events.filter(e=>(filter==='All'||filter==='Saved'&&saved.includes(e.id)||e.category===filter)&&(e.title+' '+e.category).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));
 return <div className="memory-page"><PageHeader title={discover?'Discover.':'What’s on.'} subtitle="Find your kind of evening at Kesari." onHome={onHome}/><div className="memory-search"><Search size={18}/><input aria-label="Search events" placeholder="Search events or workshops…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="memory-filters">{['All','Music','Workshops','Community','Saved'].map(c=><button key={c} className={c===filter?'active':''} onClick={()=>setFilter(c)} aria-pressed={c===filter}>{c}</button>)}</div>{error&&<p className="booking-error" role="alert">{error}</p>}<div className="memory-events-grid">{visible.map(e=><article className="memory-event" key={e.id}><img src={eventImage(e)} alt=""/><div className="memory-event-top"><span>{e.featured?'Featured · ':''}{e.category}</span><button aria-label={`Save ${e.title}`} aria-pressed={saved.includes(e.id)} onClick={()=>onSave(e.id)}><Heart size={19} fill={saved.includes(e.id)?'currentColor':'none'}/></button></div><button className="memory-event-open" onClick={()=>onSelect(e.id)}><small>{dateLabel(e.date)} · {timeLabel(e.date)}</small><h2>{e.title}</h2><span className="memory-event-bottom"><span>{Date.parse(e.date)<=Date.now()?'Past event':e.price==null?'Price to be announced':money(e.price)}</span><i><ArrowUpRight size={19}/></i></span></button></article>)}</div>{!visible.length&&<div className="memory-empty"><Ticket size={32}/><h2>{loading?'Loading events…':'More memories on the way.'}</h2><p>{filter==='Saved'?'Save an event with its heart button to keep it here.':'Published events will appear here as soon as the Kesari team adds them.'}</p></div>}</div>
}

function PaymentForm({event,onOrder,onTickets,resumeOrder}){
 const[order,setOrder]=useState(resumeOrder||null),[quantity,setQuantity]=useState(1),[error,setError]=useState(''),[busy,setBusy]=useState(false);const requestKey=useRef(null),panel=useRef(null);if(!requestKey.current)requestKey.current=createRequestKey();const[resuming,setResuming]=useState(!!resumeOrder),[resumeFailed,setResumeFailed]=useState(false);
 useEffect(()=>{if(order&&!resuming)revealBooking(panel.current)},[order?.id,order?.status,resuming]);
 useEffect(()=>{if(!resumeOrder)return;let live=true;api('/api/orders/'+resumeOrder.id,{headers:{Authorization:'Bearer '+resumeOrder.token}}).then(next=>{if(live){const updated={...resumeOrder,...next};setOrder(updated);onOrder(updated)}}).catch(e=>{if(live){setError(e.message);setResumeFailed(true)}}).finally(()=>{if(live)setResuming(false)});return()=>{live=false}},[]);
 async function create(e){e.preventDefault();if(busy)return;setBusy(true);setError('');try{const form=new FormData(e.currentTarget),o=await api('/api/orders',{method:'POST',body:JSON.stringify({...Object.fromEntries(form),eventId:event.id,acceptedTerms:form.has('acceptedTerms'),requestKey:requestKey.current})});setOrder(o);onOrder(o)}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function submit(e){e.preventDefault();if(busy)return;setBusy(true);setError('');try{const d=await api(`/api/orders/${order.id}/payment`,{method:'POST',headers:{Authorization:'Bearer '+order.token},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const next={...order,...d};setOrder(next);onOrder(next)}catch(e){setError(e.message)}finally{setBusy(false)}}
 const uri=order?'upi://pay?'+new URLSearchParams({pa:order.upiId,pn:order.payeeName,am:order.amount.toFixed(2),cu:'INR',tr:order.reference,tn:order.reference}):'';
 if(resuming)return <p className="booking-notice">Retrieving your booking…</p>;if(resumeFailed)return <p className="booking-error">{error}</p>;
 return <div ref={panel} className="event-booking-form">{order?['pending_review','confirmed','rejected'].includes(order.status)?<><span className="booking-success-icon"><Check/></span><h3>{order.status==='confirmed'?'Your ticket is confirmed.':order.status==='rejected'?'Booking declined.':'Payment sent for review.'}</h3><p>{order.status==='confirmed'?'Your admission pass is ready in My tickets.':order.status==='rejected'?'Contact Kesari about your payment.':'Your ticket appears after Kesari checks the transaction and confirms availability.'}</p><p className="booking-notice">{order.reference} · {order.status.replaceAll('_',' ')}</p><button className="memory-action" onClick={onTickets}>View my tickets <ArrowUpRight size={17}/></button></>:<><h3>Pay with UPI</h3><div className="booking-total"><span>{order.quantity} ticket(s)</span><strong>{money(order.amount)}</strong></div><p>Pay <strong>{order.payeeName}</strong><br/>{order.upiId}</p><CodeImage value={uri}/><a className="memory-action" href={uri}>Open UPI app <ArrowUpRight size={17}/></a><p className="memory-muted">On desktop, scan with your phone. Check the payee and amount before paying.</p><div className="booking-notice">{order.reference}<br/>Payment is unverified. This request does not reserve seats.</div><form onSubmit={submit}><label>UPI transaction reference<input name="utr" required pattern="[A-Za-z0-9-]{8,40}" maxLength={40} placeholder="From your UPI app"/></label><button className="memory-action" disabled={busy}>{busy?'Submitting…':'Submit for verification'} <ArrowUpRight size={17}/></button></form></>:<form onSubmit={create}><h3>Book your evening.</h3><label>Your name<input name="name" autoComplete="name" required maxLength={80}/></label><label>Email<input name="email" type="email" autoComplete="email" required maxLength={150}/></label><label>Phone<input name="phone" type="tel" autoComplete="tel" required pattern="[+0-9 ()-]{10,18}" maxLength={18}/></label><label>Tickets<select name="quantity" value={quantity} onChange={e=>setQuantity(Number(e.target.value))}>{Array.from({length:Math.min(6,event.remaining??6)},(_,i)=><option key={i} value={i+1}>{i+1}</option>)}</select></label><div className="booking-total"><span>Total</span><strong>{money(event.price*quantity)}</strong></div><p className="booking-terms">{event.terms}</p><p className="memory-muted">UPI payments are checked manually. Admission is confirmed after payment and capacity verification.</p><label className="booking-consent"><input type="checkbox" name="acceptedTerms" required/> I agree to these booking terms.</label><button className="memory-action" disabled={busy}>{busy?'Preparing…':'Continue to UPI'} <ArrowUpRight size={17}/></button></form>}{error&&<p className="booking-error" role="alert">{error}</p>}</div>
}

export function EventBooking({event,settings,onBack,onOrder,onTickets,saved,onSave,loading,resumeOrder}){
 if(!event)return <div className="memory-page"><PageHeader title={loading?'Loading event…':'This event is unavailable.'} subtitle={loading?'':'It may have been unpublished. Explore the other experiences at Kesari.'} onHome={onBack}/></div>;
 const past=Date.parse(event.date)<=Date.now(),ready=event.bookingOpen&&!past&&(event.remaining??1)>0,upi=ready&&event.bookingMode==='upi'&&event.price>0&&settings.payeeName;
 function jumpToBooking(e){revealBooking(e.currentTarget.closest('.live-event-layout').querySelector('.live-booking-panel'))}
 return <div className="memory-page"><PageHeader title={event.title} subtitle="Kesari · The Memory Studio, Koramangala" onHome={onBack}/><div className="live-event-layout"><div className="live-event-story"><div className="live-event-hero"><img className="live-event-cover" src={eventImage(event)} alt={event.title}/><button className="memory-action event-book-jump" onClick={jumpToBooking}>{ready?'Book tickets':'Booking details'}<ArrowUpRight size={17}/></button></div><p className="memory-overline" style={{marginTop:25}}>{event.featured?'FEATURED · ':''}{event.category}</p><h2 className="live-event-subtitle">About this event.</h2><p className="live-event-description">{event.description}</p><button className="memory-save" onClick={()=>onSave(event.id)} aria-pressed={saved.includes(event.id)}><Heart size={17} fill={saved.includes(event.id)?'currentColor':'none'}/>{saved.includes(event.id)?'Saved':'Save this event'}</button></div><aside className="live-booking-panel"><p className="booking-meta"><CalendarDays size={17}/>{dateLabel(event.date)} · {timeLabel(event.date)}</p><p className="booking-meta"><MapPin size={17}/>Koramangala, Bengaluru</p><div className="booking-total"><span>Per guest</span><strong>{event.price==null?'To be announced':money(event.price)}</strong></div>{upi||resumeOrder&&resumeOrder.status!=='awaiting_payment'?<PaymentForm key={event.id} event={event} onOrder={onOrder} onTickets={onTickets} resumeOrder={resumeOrder}/>:ready&&event.bookingMode==='external'&&event.externalUrl?<><a className="memory-action" href={event.externalUrl} target="_blank" rel="noreferrer">Book on event partner <ArrowUpRight size={17}/></a><p className="memory-muted">{event.terms}</p></>:<><p className="booking-notice">{past?'This event has ended.':event.remaining===0?'This event is sold out.':event.bookingOpen?'Payment setup is being completed. Please contact Kesari.':'Bookings are not open yet.'}</p><a className="memory-action" href={'tel:'+settings.phone}>Ask Kesari <ArrowUpRight size={17}/></a></>}</aside></div></div>
}

export function LiveTickets({orders,onUpdate,onHome,onEvents,onResume,events=[]}){
 const[error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function refresh(){setBusy(true);setError('');try{for(const o of orders){const next=await api('/api/orders/'+o.id,{headers:{Authorization:'Bearer '+o.token}});onUpdate({...o,...next})}}catch(e){setError(e.message)}finally{setBusy(false)}}
 useEffect(()=>{if(orders.length)refresh()},[]);
 return <div className="memory-page"><PageHeader title="My tickets." subtitle="Your booking requests and confirmed passes." onHome={onHome}/>{error&&<p className="booking-error">{error}</p>}{!orders.length?<div className="memory-empty tickets-empty"><Ticket size={40}/><h2>No tickets here yet.</h2><button className="memory-action" onClick={onEvents}>Explore events <ArrowUpRight size={17}/></button></div>:<><button className="memory-action" onClick={refresh} disabled={busy}><RefreshCw size={16}/>{busy?'Refreshing…':'Refresh booking status'}</button><div className="live-tickets-grid">{orders.map(o=><article className="live-ticket" key={o.id}>{events.find(e=>e.id===o.eventId)&&<img className="live-ticket-cover" src={eventImage(events.find(e=>e.id===o.eventId))} alt=""/>}<span className="memory-overline">KESARI · THE MEMORY STUDIO</span><h2>{o.eventTitle}</h2><p>{dateLabel(o.eventDate)} · {o.quantity} guest(s)</p><span className={'ticket-status '+o.status}>{o.status.replaceAll('_',' ')}</span>{o.status==='confirmed'&&o.ticketCode?<><CodeImage value={'KESARI:'+o.ticketCode}/><p>Show this pass at Kesari.</p><button className="memory-action" onClick={()=>window.print()}><Printer size={16}/>Print ticket</button></>:<p className="memory-muted">{o.status==='pending_review'?'The team will confirm after checking your payment.':o.status==='rejected'?'The booking was declined. Contact Kesari about your payment.':'Payment details have not been submitted yet.'}</p>}<small>{o.reference}</small>{o.status==='awaiting_payment'&&<button className="memory-action" style={{marginTop:15}} onClick={()=>onResume(o)}>Continue payment <ArrowUpRight size={16}/></button>}</article>)}</div><p className="memory-muted">Your private booking key is saved in this browser. Keep your reference if you change devices.</p></>}</div>
}

