/* Root Application Layout */
.hyperactive-showcase-root {
  width: 100%;
  min-height: 100vh;
  background-color: var(--color-obsidian);
  color: var(--color-warm-ivory);
  position: relative;
  overflow-x: hidden;
}

/* Full Website Global Background */
.global-website-backdrop {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.global-backdrop-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
  transform: scale(1.02);
}

.global-backdrop-overlay {
  position: absolute;
  inset: 0;
  background: 
    radial-gradient(circle at 50% 18%, rgba(255, 130, 72, 0.2) 0%, rgba(10, 10, 10, 0.72) 48%, #0A0A0A 100%),
    linear-gradient(180deg, rgba(10, 10, 10, 0.62) 0%, rgba(10, 10, 10, 0.8) 45%, rgba(10, 10, 10, 0.93) 100%);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

/* Main Presentation Surface */
.presentation-canvas {
  width: 100%;
  min-height: 100vh;
  position: relative;
  z-index: 1;
}

/* Continuous Stream (Behance Mode) */
.behance-continuous-stream {
  display: flex;
  flex-direction: column;
  width: 100%;
}

.stream-section {
  width: 100%;
  position: relative;
}

/* Single Slide Fullscreen Mode */
.single-slide-fullscreen {
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Standalone Mobile Canvas */
.standalone-mobile-canvas {
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px 100px 20px;
  background: radial-gradient(circle at 50% 30%, #171926 0%, #080808 85%);
}

/* Floating Discreet Slide Navigation Dock at Bottom Center */
.floating-presentation-dock {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all var(--transition-smooth);
}

.floating-presentation-dock.collapsed {
  bottom: 20px;
  right: 20px;
  left: auto;
  transform: none;
}

.dock-pill-bar {
  background: rgba(15, 17, 25, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 9999px;
  padding: 6px 10px;
  display: flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.65), 0 0 20px rgba(0, 0, 0, 0.3);
}

.dock-btn {
  background: transparent;
  color: #9CA3AF;
  font-family: var(--font-family-display);
  font-size: 13px;
  font-weight: 600;
  padding: 8px 14px;
  border-radius: 9999px;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.dock-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--color-pure-white);
}

.dock-btn.active {
  background: rgba(255, 255, 255, 0.2);
  color: var(--color-pure-white);
}

.dock-btn.lime-dock-btn.active {
  background: var(--color-electric-lime);
  color: #080808;
  font-weight: 700;
  box-shadow: var(--shadow-lime);
}

.dock-toggle-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #181A24;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--color-pure-white);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5);
  transition: transform var(--transition-fast);
}

.dock-toggle-btn:hover {
  transform: scale(1.08);
  background: #252838;
}

@media (max-width: 900px) {
  .dock-pill-bar {
    max-width: 92vw;
    overflow-x: auto;
    padding: 6px 8px;
  }
}

